{
  "thought": "I need to write the implementation for critical_roads. The logic is: 1) Count edges between each pair of nodes. If count > 1, skip (parallel roads). 2) For pairs with count == 1, remove that edge and check connectivity. 3) Use BFS to check if the two endpoints are still connected. I'll write the complete file now.",
  "action": {
    "tool": "write_file",
    "args": {
      "path": "src/routekit/critical_roads.py",
      "content": "from __future__ import annotations

from typing import Any, Dict, Iterable, List, Mapping, Optional, Sequence, Set, Tuple, Union
from collections import defaultdict, deque


def critical_roads(edges: Iterable[Tuple[str, str, int]]) -> List[Tuple[str, str]]:
    """
    Find the roads whose closure would cut a region in two.

    Roads are undirected and the network is built with ``build_adjacency``. A road
    between depots ``a`` and ``b`` is critical if, once it is closed, ``b`` can no
    longer be reached from ``a``. Self-loops are never critical. Networks are small (a
    few dozen roads), so checking each road separately is fine.

    Returns the critical roads as ``(code_a, code_b)`` pairs with ``code_a < code_b``,
    sorted, each road listed once.

    Example:
        critical_roads([("A", "B", 1), ("B", "C", 1), ("C", "A", 1), ("C", "D", 4)]) == [("C", "D")]
    """
    edge_list = list(edges)

    # Count edges between each pair of nodes (normalized: a < b)
    edge_counts: Dict[Tuple[str, str], int] = defaultdict(int)

    for a, b, _ in edge_list:
        if a == b:
            continue
        pair = (a, b) if a < b else (b, a)
        edge_counts[pair] += 1

    critical: List[Tuple[str, str]] = []

    # For each unique pair with exactly one edge, check if it's critical
    for (a, b), count in edge_counts.items():
        if count != 1:
            continue

        # Build adjacency without this specific edge
        adj: Dict[str, List[str]] = defaultdict(list)
        for x, y, _ in edge_list:
            if x == y:
                continue
            pair = (x, y) if x < y else (y, x)
            if pair == (a, b):
                continue
            adj[x].append(y)
            adj[y].append(x)

        # Check if a and b are still connected using BFS
        if not _is_connected(adj, a, b):
            critical.append((a, b))

    return sorted(critical)


def _is_connected(adj: Dict[str, List[str]], start: str, end: str) -> bool:
    """Check if start and end are connected in the graph using BFS."""
    if start == end:
        return True

    visited: Set[str] = set()
    queue: deque = deque([start])
    visited.add(start)

    while queue:
        node = queue.popleft()
        for neighbor in adj.get(node, []):
            if neighbor == end:
                return True
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)

    return False
"
