import heapq
from typing import Mapping, Optional, Tuple, List, Dict, Set


def shortest_path(adj: Mapping[str, Mapping[str, int]], src: str, dst: str) -> Optional[Tuple[int, List[str]]]:
    """
    Find the shortest route by road length between two depots.

    ``adj`` is an adjacency map as built by ``build_adjacency`` (directed or not) with
    non-negative km values. Returns ``(total_km, path)`` where ``path`` lists the depot
    codes from ``src`` to ``dst`` inclusive; ``src == dst`` gives ``(0, [src])``.
    Returns None when ``dst`` cannot be reached from ``src``.

    Real networks often contain several routes of equal length; the function must
    always return the same route for the same network, independent of dict insertion
    order.

    Raises KeyError if ``src`` or ``dst`` is not a key of ``adj``.

    Example:
        net = {"A": {"B": 2}, "B": {"A": 2, "C": 3}, "C": {"B": 3}}
        shortest_path(net, "A", "C") == (5, ["A", "B", "C"])
    """
    # Raise KeyError if src or dst not in adj
    if src not in adj:
        raise KeyError(src)
    if dst not in adj:
        raise KeyError(dst)

    # Handle src == dst case
    if src == dst:
        return (0, [src])

    # Dijkstra's algorithm with deterministic tie-breaking
    # We use (distance, path_tuple) in the heap to ensure deterministic ordering
    # when distances are equal - paths are compared lexicographically

    best_dist: Dict[str, int] = {src: 0}
    best_path: Dict[str, Tuple[str, ...]] = {src: (src,)}

    # Priority queue: (distance, path_tuple)
    pq: List[Tuple[int, Tuple[str, ...]]] = [(0, (src,))]

    visited: Set[str] = set()

    while pq:
        dist, path_tuple = heapq.heappop(pq)
        node = path_tuple[-1]

        if node in visited:
            continue

        visited.add(node)

        if node == dst:
            return (dist, list(path_tuple))

        # Get neighbors and sort them deterministically by node name
        neighbors = adj.get(node, {})
        sorted_neighbors = sorted(neighbors.items(), key=lambda x: x[0])

        for neighbor, weight in sorted_neighbors:
            if neighbor in visited:
                continue
            new_dist = dist + weight
            new_path = path_tuple + (neighbor,)

            # Update if we found a shorter path, or same distance but lexicographically smaller path
            if neighbor not in best_dist or new_dist < best_dist[neighbor] or (new_dist == best_dist[neighbor] and new_path < best_path[neighbor]):
                best_dist[neighbor] = new_dist
                best_path[neighbor] = new_path
                heapq.heappush(pq, (new_dist, new_path))

    # dst not reachable
    return None
