from itertools import permutations
from typing import List, Mapping, Optional, Sequence, Tuple

from routekit.shortest_path import shortest_path


def plan_drop_route(
    adj: Mapping[str, Mapping[str, int]],
    origin: str,
    destination: str,
    drops: Sequence[str],
) -> Optional[Tuple[int, List[str]]]:
    if len(drops) != len(set(drops)):
        raise ValueError("drops contains duplicates")
    if len(drops) > 6:
        raise ValueError("drops contains more than 6 depots")
    for node in [origin, destination] + list(drops):
        if node not in adj:
            raise KeyError(node)
    if not drops:
        return shortest_path(adj, origin, destination)
    best_result: Optional[Tuple[int, List[str]]] = None
    best_legs: int = float("inf")
    best_drop_order: Optional[Tuple[str, ...]] = None
    for perm in permutations(drops):
        waypoints = [origin] + list(perm) + [destination]
        total_distance = 0
        full_path: List[str] = []
        valid = True
        for i in range(len(waypoints) - 1):
            segment = shortest_path(adj, waypoints[i], waypoints[i + 1])
            if segment is None:
                valid = False
                break
            seg_dist, seg_path = segment
            total_distance += seg_dist
            if i == 0:
                full_path = seg_path[:]
            else:
                full_path.extend(seg_path[1:])
        if not valid:
            continue
        num_legs = len(waypoints) - 1
        is_better = False
        if best_result is None:
            is_better = True
        elif total_distance < best_result[0]:
            is_better = True
        elif total_distance == best_result[0]:
            if num_legs < best_legs:
                is_better = True
            elif num_legs == best_legs and (best_drop_order is None or perm < best_drop_order):
                is_better = True
        if is_better:
            best_result = (total_distance, full_path)
            best_legs = num_legs
            best_drop_order = perm
    return best_result"}}, "messages": []}

